@MvPolynomial.degreeOf_add_le : ∀ {R : Type u_1} {σ : Type u_2} [inst : CommSemiring R] (n : σ)
  (f g : MvPolynomial σ R),
  MvPolynomial.degreeOf n (f + g) ≤ max (MvPolynomial.degreeOf n f) (MvPolynomial.degreeOf n g)

@MvPolynomial.degreeOf_prod_le : ∀ {R : Type u_1} {σ : Type u_2} [inst : CommSemiring R] {ι : Type u_3} (i : σ)
  (s : Finset ι) (f : ι → MvPolynomial σ R),
  MvPolynomial.degreeOf i (∏ j ∈ s, f j) ≤ ∑ j ∈ s, MvPolynomial.degreeOf i (f j)

@MvPolynomial.aeval_natDegree_le : ∀ {σ : Type u_1} {R : Type u_2} [inst : CommSemiring R] {m n : ℕ}
  (F : MvPolynomial σ R),
  F.totalDegree ≤ m →
    ∀ (f : σ → Polynomial R), (∀ (i : σ), (f i).natDegree ≤ n) → ((MvPolynomial.aeval f) F).natDegree ≤ m * n
